mapper.update:
UPDATE task_completion_record
SET total_minutes    = #{totalMinutes},
    first_started_at = #{firstStartedAt},
    last_ended_at    = #{lastEndedAt}
WHERE workspace_id = #{workspaceId} AND task_id = #{taskId}

mapper.select:
SELECT COUNT(*) FROM task_completion_record
WHERE workspace_id = #{workspaceId}
  AND completed_at >= #{from}
  AND completed_at < #{to}

SELECT COUNT(*) AS total,
       COALESCE(SUM(r.total_minutes), 0) AS total_minutes,
       COUNT(DISTINCT COALESCE(r.owner, '未指派')) AS owner_count
FROM task_completion_record r
WHERE r.workspace_id = #{workspaceId}
  AND r.completed_at >= #{from}
  AND r.completed_at < #{to}

SELECT COALESCE(r.owner, '未指派') AS owner, COUNT(*) AS owner_count
FROM task_completion_record r
WHERE r.workspace_id = #{workspaceId}
  AND r.completed_at >= #{from}
  AND r.completed_at < #{to}

GROUP BY COALESCE(r.owner, '未指派')
ORDER BY owner_count DESC, MAX(r.completed_at) DESC, owner ASC
LIMIT 1

SELECT r.id, r.workspace_id, r.task_id, r.title, r.description, r.req_id, r.req_name,
       r.req_doc_id, r.req_doc_title, r.owner, r.owner_user_id, r.category, r.priority,
       r.start_date, r.completed_at, r.first_started_at, r.last_ended_at, r.total_minutes, r.created_at
FROM task_completion_record r
WHERE r.workspace_id = #{workspaceId}
  AND r.completed_at >= #{from}
  AND r.completed_at < #{to}

ORDER BY r.completed_at DESC, r.id DESC
LIMIT #{limit} OFFSET #{offset}
